#!/bin/bash
# The adapted stage, run on the recipes each earlier stage selected.
#
# One leader per stage, plus every recipe within one standard deviation of it,
# since at that separation the ordering between them is a property of the three
# seeds rather than of the recipes. Each is trained at the depth its frozen
# counterpart was best at, averaged over seeds: a single seed's best depth moves
# by ten layers between repeats, while the averaged profile does not.
#
# Every setting is copied from the frozen run each is compared against, the
# token budget included, so the comparison isolates the adapters. Two
# differences are forced rather than chosen: a frozen run trains a head at all
# thirty-one depths at once and an adapted one hooks a single layer, and the
# micro-batch is one answer rather than eight because the language model is
# resident. Holding the token budget therefore costs a narrow window far more
# here than it did frozen, because supervising sixty-four tokens still runs a
# whole answer through the model; the walltime each job asks for reflects that.
#
# The step cap is a backstop. The rule is expected to end these runs well before
# it, and the checkpoint each is judged on is the one recorded in
# selection_outcomes.json.
set -euo pipefail
cd /iopsstor/scratch/cscs/mdenegri/degeneration-probe

# S1: rollout_balanced W=128/centered hard h=0 bce
#     frozen counterpart 0.0423 +/- 0.0026 at depth 15; 33 answers per step
sbatch --time=12:00:00 cluster/train.sbatch training.features.regime=adapted training.lora.enabled=true training.lora.layers=all training.lora.rank=16 training.optimizer.lora_learning_rate=1e-5 training.optimizer.probe_learning_rate=1e-4 training.probe.layers=null training.probe.layer=15 training.selection.strategy=rollout_balanced training.selection.window_size=128 training.selection.anchor=centered training.selection.positive_fraction=0.25 training.label.family=frontier_hard training.label.horizon=0 training.label.decay=exponential training.label.decay_length=256 training.label.signal=repetition_score training.loss.name=bce training.loss.bce.use_pos_weight=true training.budget.tokens_per_step=4096 training.runtime.per_device_train_batch_size=1 training.runtime.seed=42 training.runtime.max_steps=2000 training.validation.strategy=steps training.validation.steps=50 training.validation.max_rollouts=null 'training.validation.final_splits=[]' training.checkpoint.strategy=steps training.checkpoint.steps=50 training.checkpoint.save_total_limit=null training.stopping.enabled=true training.stopping.floor=0.3 training.stopping.band=256 training.stopping.tolerance=0.002 training.stopping.patience=4 'training.wandb.tags=["exp:S3","carried:S1"]'
